/* Moon imagery for the Moon Phases sim, as data URIs so it also works from file:// and inside an embed.
   Source: NASA's Scientific Visualization Studio, CGI Moon Kit (https://svs.gsfc.nasa.gov/4720/),
   visualizer Ernie Wright, scientist Noah Petro; data from Lunar Reconnaissance Orbiter (LROC WAC colour, LOLA elevation). Public domain.
   color: near side, orthographic, N up, 640 px, disc radius 318 px (from lroc_color_poles_4k.tif).
   slope: two 640 px grey tiles, -dh/dx and -dh/dy in the view plane, sign * sqrt(|g|/0.3) (from ldem_16_uint.tif).
   globe: the whole Moon, 128 x 64, longitude -180..180, for the small Moon in the space view. */
window.MOON_IMG = { size: 640, radius: 318, slopeMax: 0.3,
  color: 'data:image/jpeg;base64,',
  slope: 'data:image/jpeg;base64,',
  globe: 'data:image/jpeg;base64,' };
